ALTER TABLE public.flights ADD COLUMN flight_number text;
ALTER TABLE public.companies ADD COLUMN next_flight_sequence bigint NOT NULL DEFAULT 101;
WITH numbered AS (SELECT f.id,c.icao_code || (100+row_number() OVER (PARTITION BY f.company_id ORDER BY f.created_at,f.id))::text AS number FROM public.flights f JOIN public.companies c ON c.id=f.company_id) UPDATE public.flights f SET flight_number=n.number FROM numbered n WHERE n.id=f.id;
UPDATE public.companies c SET next_flight_sequence=101+(SELECT count(*) FROM public.flights f WHERE f.company_id=c.id);
CREATE UNIQUE INDEX flights_company_number_unique ON public.flights(company_id,flight_number);
ALTER TABLE public.flights ADD CONSTRAINT flight_number_format CHECK (flight_number IS NOT NULL AND flight_number ~ '^[A-Z][A-Z0-9]{2,11}$');
CREATE FUNCTION public.assign_flight_number() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.companies%ROWTYPE; candidate text; seq bigint; BEGIN SELECT * INTO c FROM public.companies WHERE id=NEW.company_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Company not found'; END IF; seq:=c.next_flight_sequence; LOOP candidate:=c.icao_code||seq::text; seq:=seq+1; EXIT WHEN NOT EXISTS(SELECT 1 FROM public.flights WHERE company_id=c.id AND flight_number=candidate); END LOOP; NEW.flight_number:=coalesce(nullif(upper(trim(NEW.flight_number)),''),candidate); UPDATE public.companies SET next_flight_sequence=seq WHERE id=c.id; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_flight_number() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER assign_flight_number BEFORE INSERT ON public.flights FOR EACH ROW EXECUTE FUNCTION public.assign_flight_number();
CREATE FUNCTION public.next_flight_number() RETURNS text LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$ DECLARE c public.companies%ROWTYPE; seq bigint; candidate text; BEGIN SELECT * INTO c FROM public.companies WHERE user_id=auth.uid(); IF NOT FOUND THEN RETURN NULL; END IF; seq:=c.next_flight_sequence; LOOP candidate:=c.icao_code||seq::text; EXIT WHEN NOT EXISTS(SELECT 1 FROM public.flights WHERE company_id=c.id AND flight_number=candidate); seq:=seq+1; END LOOP; RETURN candidate; END $$;
REVOKE ALL ON FUNCTION public.next_flight_number() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.next_flight_number() TO authenticated;
CREATE FUNCTION public.dispatch_flight(p_aircraft uuid,p_destination text,p_flight_number text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE fid uuid; number text:=nullif(upper(trim(p_flight_number)),''); BEGIN IF number IS NOT NULL AND number !~ '^[A-Z][A-Z0-9]{2,11}$' THEN RAISE EXCEPTION 'Flight number must contain 3–12 letters or digits and start with a letter'; END IF; fid:=public.dispatch_flight(p_aircraft,p_destination); IF number IS NOT NULL THEN BEGIN UPDATE public.flights SET flight_number=number WHERE id=fid AND company_id IN(SELECT id FROM public.companies WHERE user_id=auth.uid()); EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'Flight number already used by your company'; END; END IF; RETURN fid; END $$;
REVOKE ALL ON FUNCTION public.dispatch_flight(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.dispatch_flight(uuid,text,text) TO authenticated;
DO $$ DECLARE definition text; old_expression text:='item.kind||'' – ''||(SELECT registration FROM public.fleet_aircraft WHERE id=f.aircraft_id AND company_id=c.id)||'' · ''||f.origin_icao||'' → ''||f.destination_icao||'' (#''||left(f.id::text,8)||'')'''; new_expression text:='item.kind||'' – ''||f.flight_number||'' · ''||(SELECT registration FROM public.fleet_aircraft WHERE id=f.aircraft_id AND company_id=c.id)||'' · ''||f.origin_icao||'' → ''||f.destination_icao'; BEGIN SELECT pg_get_functiondef('public.settle_flight(uuid,jsonb)'::regprocedure) INTO definition; IF position(old_expression IN definition)=0 THEN RAISE EXCEPTION 'Settlement identity expression not found'; END IF; EXECUTE replace(definition,old_expression,new_expression); END $$;
CREATE FUNCTION public.transaction_history_numbered(p_company uuid,p_aircraft uuid DEFAULT NULL) RETURNS TABLE(id bigint,entry_type text,debit_account text,credit_account text,company_delta numeric,balance_after numeric,description text,reference text,created_at timestamptz,aircraft_id uuid,registration text,flight_id uuid,origin_icao text,destination_icao text,flight_number text) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT h.*,f.flight_number FROM public.transaction_history(p_company,p_aircraft) h LEFT JOIN public.flights f ON f.id=h.flight_id AND f.company_id=p_company; $$;
REVOKE ALL ON FUNCTION public.transaction_history_numbered(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.transaction_history_numbered(uuid,uuid) TO authenticated;
COMMENT ON FUNCTION public.transaction_history(uuid,uuid) IS 'DEPRECATED for app reads: replaced by transaction_history_numbered; retained as owner-scoped internal projection and compatibility API.';